/**
 * Named aliases over the generated Saifuro schema. `schema.d.ts` is generated by
 * `bun run gen:types` from `spec/saifuro-openapi.yaml` and never edited by hand.
 * Every Saifuro shape this app uses is named here, from the schema, never retyped.
 */
import type { components } from "./schema";

type Schemas = components["schemas"];

export type Agent = Schemas["Agent"];
export type Mandate = Schemas["Mandate"];
export type MandateCreate = Schemas["MandateCreate"];
export type MandateStatus = Mandate["status"];
export type Decision = Schemas["Decision"];
export type RequestSpec = Schemas["RequestSpec"];
export type Review = Schemas["Review"];
export type Verdict = Schemas["Verdict"];
export type EventType = Schemas["EventType"];

/** The terms a policy carries: a mandate body without its agent. */
export type MandateTerms = Omit<MandateCreate, "agent">;
